sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.request = function() {
        c.data.action = 'request';
        c.data.assetId = c.selectedAsset;
        c.server.update().then(function() {
            c.selectedAsset = '';
            c.data.action = '';
        });
    };
};

sp_widget.script:
(function() {
 // Handle the "request" button
    if (input && input.action == 'request' && input.assetId) {
        var utils = new AssetLoanUtils();
        if (!utils.isAssetAvailable(input.assetId)) {
            data.message = 'Sorry, that asset is no longer available.';
        } else {
            var due = new GlideDateTime();
            due.addDaysUTC(7);

            var req = new GlideRecord('x_2228927_asset_0_loan_request');
            req.initialize();
            req.asset = input.assetId;
            req.requested_by = gs.getUserID();
            req.due_date = due.getDate();
            req.status = 'pending_approval';
            req.insert();
            data.message = 'Request submitted: ' + req.number;
        }
    }

		// My current loans
    data.loans = [];
    var loan = new GlideRecord('x_2228927_asset_0_loan_request');
    loan.addQuery('requested_by', gs.getUserID());
    loan.addQuery('status', 'IN', 'pending_approval,approved,on_loan,overdue');
    loan.orderByDesc('sys_created_on');
    loan.query();
    while (loan.next()) {
        data.loans.push({
            number: loan.getDisplayValue('number'),
            asset: loan.getDisplayValue('asset'),
            due: loan.getDisplayValue('due_date'),
            status: loan.getDisplayValue('status')
        });
    }

		// Assets available to request
		data.assets = [];
    var utils2 = new AssetLoanUtils();
    var a = utils2.getAvailableAssets();
    while (a.next()) {
        data.assets.push({
            id: a.getUniqueValue(),
            label: a.getDisplayValue('asset_tag') + ' (' + a.getDisplayValue('category') + ')'
        });
    }
})();
